import type { Example, Lesson } from '../shared/types.js';

// Original short tasks aligned to the second edition. Compact rows are expanded
// once at module load; neither the textbook text nor generated-at-runtime lessons
// are used. `kana` is a full reading, so the UI can display it without guessing.
type E = [jp: string, kana: string, zh: string];
type V = [word: string, reading: string, meaning: string, ...example: E];
type G = [title: string, explanation: string, pattern: string[], first: E, second: E];
type D = {
  title: string; lines: E[]; question: string; options: string[]; answer: number;
  explanation: string; goals: number[]; task: string; setting: string; checks: string[];
};
const example = ([jp, kana, zh]: E): Example => ({ jp, kana, zh });
// In a listening dialogue either participant can speak first. An AI scene must
// start in the assigned counterpart's role, so these openings are intentional.
const roleOpenings: Record<string, E> = {
  '5-0': ['こんにちは。どこへ行きますか。','こんにちは。どこへいきますか。','你好，要去哪里？'],
  '6-0': ['こんにちは。今日は何時に昼ご飯を食べますか。','こんにちは。きょうはなんじにひるごはんをたべますか。','你好，今天几点吃午饭？'],
  '14-1': ['今、荷物を運んでいます。','いま、にもつをはこんでいます。','现在正在搬行李。'],
  '15-0': ['こんにちは。どうぞ。','こんにちは。どうぞ。','你好，请说。'],
  '16-0': ['こんにちは。飲み物ですか。','こんにちは。のみものですか。','你好，要买饮料吗？'],
  '17-0': ['明日はタオルを持ってきてください。','あしたはたおるをもってきてください。','明天请带毛巾来。'],
  '17-1': ['このカメラは五時までです。','このかめらはごじまでです。','这台相机租到五点。'],
  '18-0': ['こんにちは。自転車ですか。','こんにちは。じてんしゃですか。','你好，是来租自行车吗？'],
  '23-0': ['こんにちは。どこへ行きますか。','こんにちは。どこへいきますか。','你好，要去哪里？'],
};
function lesson(id: number, title: string, canDo: string, gs: G[], vs: V[], ds: D[]): Lesson {
  const prefix = `l${String(id).padStart(2, '0')}`;
  const grammar = gs.map(([title, explanation, pattern, a, b], i) => ({
    id: `${prefix}-g${i + 1}`, title, explanation, pattern, examples: [example(a), example(b)],
  }));
  return {
    id, volume: 1, title, canDo,
    prerequisiteLessonIds: Array.from({ length: id - 1 }, (_, i) => i + 1), grammar,
    vocabulary: vs.map(([word, reading, meaning, jp, kana, zh]) => ({ word, reading, meaning, example: { jp, kana, zh } })),
    listening: ds.map((d, i) => ({ id: `${prefix}-listen${i + 1}`, title: d.title, lines: d.lines.map(example), question: d.question,
      options: d.options, answer: d.answer, explanation: d.explanation, grammarIds: d.goals.map(g => grammar[g - 1]!.id) })),
    // Six retrieval tasks cover every grammar item before repeating an item.
    // These deliberately reuse the teaching examples, enabling prompt fading.
    speaking: Array.from({ length: 6 }, (_, i) => {
      const g = grammar[i % grammar.length]!;
      const answer = g.examples[Math.floor(i / grammar.length) % 2]!;
      return { id: `${prefix}-speak${i + 1}`, goal: answer.zh, hint: g.pattern.join(' → '), answer, grammarId: g.id };
    }),
    scenarios: ds.map((d, i) => ({ id: `${prefix}-scene${i + 1}`, title: d.title, goal: d.task, setting: d.setting,
      opening: example(roleOpenings[`${id}-${i}`] ?? d.lines[0]!), targetGrammarIds: d.goals.map(g => grammar[g - 1]!.id), successCriteria: d.checks })),
  };
}

